SELECT '==DESCRIBE ASSIGN_OVERRIDES==' as '';
DESCRIBE isi_assign_overrides;
SELECT '==CHECK IF ASSIGN 519 WAS EVER DIFFERENT (TIME GAP)==';
SELECT 'timecreated' AS col, MIN(from_unixtime(timecreated)) AS min_created, MAX(from_unixtime(timemodified)) AS last_mod FROM (SELECT timecreated, timemodified FROM isi_assign WHERE id = 519) x;
SELECT '==COURSE_MODULE TIMELINE FOR 9554==' as '';
SELECT id, course, section, instance, module, added, deletioninprogress, visible FROM isi_course_modules WHERE id = 9554;
SELECT '==ALL ASSIGNS WITH SAME NAME IN COURSE 87==' as '';
SELECT id, course, name, duedate, timemodified, timecreated FROM isi_assign WHERE course = 87 AND name LIKE '%CAPAS DE LA ATMOSFERA%' OR (course = 87 AND name LIKE '%PALABRA METEOROLOGIA%');
SELECT '==CHECK IF THERE IS GRADING ACTIVITY IN ASSIGN 519 LATEST==' as '';
SELECT id, eventname, action, userid AS grader, relateduserid, from_unixtime(timecreated) dt FROM isi_logstore_standard_log WHERE contextinstanceid = 9554 AND eventname LIKE '%grade%' ORDER BY timecreated DESC LIMIT 30;
SELECT '==LIST ALL GRADED SUBMISSIONS IN ASSIGN 519 (for compare with student 2735)==';
SELECT s.id, s.userid, u.firstname, u.lastname, s.status, s.attemptnumber, s.latest FROM isi_assign_submission s JOIN isi_user u ON u.id = s.userid WHERE s.assignment = 519 ORDER BY s.id DESC LIMIT 30;
